import {createShiftGame} from './shift-floor.js?v=0.4.0';
import {PODS,CASES,CASE_BY_ID} from './cases.js';
import {deviceDisplay} from './device.js';
import {CLINICAL_SOURCES} from './sources.js?v=0.4.0';
import {newRun,time,observe,act,finish,metrics,remaining,noteCompleteness,albuminVolume} from './engine.js';

const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const KEY='shift-icu-v1';
let data={runs:{},mode:'coached',review:{}};
try{const saved=JSON.parse(localStorage.getItem(KEY)||'null');if(saved&&saved.runs)data={...data,...saved};}catch{}
let screen='hub',podId='delta',caseId=null,tab='brief',frame=0,toastTimer,activeSpeech=null,sound=false,audioContext,musicTimer;
let mapPlayer={x:480,y:260},pressed=new Set();
const app=$('#app');
let floorGame=null;
function openShift(id='delta'){stopSpeech();cancelAnimationFrame(frame);pressed.clear();floorGame?.destroy();screen='shift';caseId=null;floorGame=createShiftGame({app,onExit:()=>{floorGame=null;screen='hub';render(false);}});floorGame.start(id);window.scrollTo(0,0);}
const save=()=>{try{localStorage.setItem(KEY,JSON.stringify(data));return true;}catch{return false;}};
const run=()=>data.runs[caseId];
function toast(text,safety=false){const el=$('#toast');el.textContent=text;el.className='toast'+(safety?' safety':'');el.hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.hidden=true,safety?18000:12000);}
$('#toast').addEventListener('click',()=>$('#toast').hidden=true);
function playTone(freq=600,duration=.09){if(!sound||!audioContext)return;try{const o=audioContext.createOscillator(),g=audioContext.createGain();o.type='square';o.frequency.value=freq;g.gain.setValueAtTime(.018,audioContext.currentTime);g.gain.exponentialRampToValueAtTime(.0001,audioContext.currentTime+duration);o.connect(g);g.connect(audioContext.destination);o.start();o.stop(audioContext.currentTime+duration);}catch{}}
function toggleSound(){sound=!sound;if(sound){try{audioContext||=new (window.AudioContext||window.webkitAudioContext)();audioContext.resume();let beat=0;const melody=[261.63,329.63,392,329.63,293.66,349.23,440,349.23];musicTimer=setInterval(()=>{if(!document.hidden)playTone(melody[beat++%melody.length],.1);},550);playTone();}catch{sound=false;toast('Sound is unavailable in this browser.');}}else clearInterval(musicTimer);$('#soundBtn').innerHTML='♫ <span>'+(sound?'ON':'OFF')+'</span>';$('#soundBtn').setAttribute('aria-pressed',String(sound));$('#soundBtn').setAttribute('aria-label',sound?'Disable game sound':'Enable game sound');}
const portrait=`<svg class="nurse-portrait" viewBox="0 0 48 52" role="img" aria-label="Your incoming nurse" shape-rendering="crispEdges"><path fill="#0a151e" d="M2 0h44v50H2z"/><path fill="#4a3532" d="M13 5h22v7H9v15h7V14h20v-4h-3z"/><path fill="#d7a47c" d="M14 13h21v17H14zM17 30h13v8H17z"/><path fill="#152635" d="M18 18h3v4h-3zm11 0h3v4h-3z"/><path fill="#9f665b" d="M22 25h6v2h-6z"/><path fill="#76d5ba" d="M10 35h27v15H10zM5 40h5v10H5zm32 0h5v10h-5z"/><path fill="#397e76" d="M20 35h9v6h-9z"/><path fill="#edf4e9" d="M31 41h4v6h-4z"/></svg>`;
function openPod(id){podId=id;screen='pod';render(false);playTone(420);}
function openCase(id,restart=false){caseId=id;podId=CASE_BY_ID[id].pod;if(restart||!data.runs[id])data.runs[id]=newRun(id,data.mode);screen=data.runs[id].finished?'debrief':'case';tab='brief';save();render(false);playTone(520);}
function render(keep=true){floorGame?.destroy();floorGame=null;stopSpeech();const scroll=window.scrollY;cancelAnimationFrame(frame);pressed.clear();if(screen==='hub')renderHub();if(screen==='pod')renderPod();if(screen==='case')renderCase();if(screen==='debrief')renderDebrief();if(!keep)window.scrollTo(0,0);else window.scrollTo(0,scroll);}
function renderHub(){const complete=Object.values(data.runs).filter(r=>r.finished).length;const incomplete=Object.values(data.runs).filter(r=>!r.finished&&r.history.length).at(-1);
 app.innerHTML=`<section class="hero"><div class="hero-copy"><p class="eyebrow">19:00 · YOUR SHIFT STARTS HERE</p><h1>Four pods.<br>One nurse.<br><em>Your next decision.</em></h1><p>Spot the clues. Fill your gray bin. Dodge the interruptions. It is your shift—with better music in your head.</p><div class="buttons"><button class="primary" data-do="start">Clock in <span>→</span></button>${incomplete?`<button class="secondary" data-do="case" data-id="${incomplete.id}">Resume case</button>`:`<button class="secondary" data-do="how">How to play</button>`}</div><div class="hero-stats"><div><b>04</b><span>CLINICAL PODS</span></div><div><b>${String(CASES.length).padStart(2,'0')}</b><span>FOCUSED CASES</span></div><div><b>${String(complete).padStart(2,'0')}</b><span>HANDOFFS COMPLETED</span></div></div></div><div class="map-shell"><div class="map-head"><span>HOSPITAL / FLOOR 01</span><span>PIXEL SHIFT</span></div><canvas id="hospitalMap" width="960" height="520" role="img" aria-label="Four-pod hospital map: Alpha IMC, Bravo medical, Charlie neuro, Delta cardiac. Select a pod using the cards below or tap a room."></canvas><div class="map-bottom"><div class="map-hint">Tap a pod, or walk with the arrows.<br>Choose a pod for a new floor assignment.</div><div class="map-foot"><div class="dpad" aria-label="Map movement"><button data-move="up" aria-label="Move up">▲</button><button data-move="left" aria-label="Move left">◀</button><button data-move="down" aria-label="Move down">▼</button><button data-move="right" aria-label="Move right">▶</button></div><button class="secondary" data-do="interact">Enter</button></div></div></div></section><div class="section-heading"><h2>Choose your pod</h2><p>The rooms and patients change with each assignment.</p></div><section class="pod-grid" aria-label="Clinical pods">${PODS.map(p=>{const n=CASES.filter(c=>c.pod===p.id).length;return `<button class="pod-card" style="--pod:${p.color}" data-do="shift" data-id="${p.id}"><div class="pod-letter">${p.letter}<span aria-hidden="true">▰</span></div><h3>${p.name}</h3><div class="type">${p.type}</div><p>${p.tag}</p><span class="pod-status">START A FLOOR SHIFT →</span></button>`;}).join('')}</section><section class="callout" style="margin-top:24px"><strong>Floor shifts:</strong> cardiac surgery and Impella, medical / SLED / ventilation, neuro / EVD, and IMC assignments. Eight focused bedside cases remain available for deeper practice. Your progress saves in this browser. These are scripted teaching scenarios, not validated clinical protocols.</section><div class="buttons" style="margin-top:18px"><button class="secondary" data-do="pod" data-id="delta">Focused cardiac cases</button><button class="secondary" data-do="pod" data-id="bravo">Focused medical cases</button></div>`;
 initMap();
}
function renderPod(){const p=PODS.find(x=>x.id===podId),cases=CASES.filter(c=>c.pod===podId);app.innerHTML=`<button class="back" data-do="hub">← Hospital map</button><section class="pod-header"><div><p class="eyebrow" style="color:${p.color}">POD ${p.letter} / ${p.type}</p><h1>${p.name}<span style="color:${p.color}">.</span></h1><p>${p.text}</p><button class="primary" data-do="shift" data-id="${p.id}">Clock in for a floor shift →</button></div><label class="mode-field">Learning mode<select id="mode"><option value="coached" ${data.mode==='coached'?'selected':''}>Coached shift</option><option value="independent" ${data.mode==='independent'?'selected':''}>Independent shift</option></select></label></section>${cases.length?`<section class="case-grid">${cases.map(c=>{const r=data.runs[c.id];return `<article class="case-card"><div class="case-meta"><span style="color:${p.color}">${c.level} / ${c.minutes}</span><span>${r?.finished?'✓ HANDOFF COMPLETE':r?.history.length?'IN PROGRESS':'READY'}</span></div><h3>${c.title}</h3><p>${c.subtitle}</p><p class="small">${c.device}</p><div class="buttons"><button class="primary" data-do="case" data-id="${c.id}">${r?.finished?'Review debrief':r?.history.length?'Resume shift':'Start shift'} →</button>${r?`<button class="quiet" data-do="replay" data-id="${c.id}">Replay</button>`:''}</div></article>`;}).join('')}</section>`:`<div class="card"><h2>Floor assignments are ready in this pod.</h2><p class="muted">Use the walkable floor for this specialty. The separate focused-case library is still being expanded.</p><button class="primary" data-do="pod" data-id="delta">Explore Delta →</button></div>`}<section class="planned"><span class="badge">FOCUSED-CASE EXPANSION PLAN</span><h3 style="margin-top:15px">Deeper focused cases in ${p.name}</h3><ul>${p.planned.map(t=>`<li>${t}</li>`).join('')}</ul><p class="helper">Every future level uses the same bedside loop: report → assessment → interpretation → ordered action → reassessment → note and handoff.</p></section>`;}
function renderCase(){const r=run(),c=CASE_BY_ID[caseId],p=PODS.find(x=>x.id===c.pod),m=metrics(r);const next=remaining(r)[0];
 app.innerHTML=`<button class="back" data-do="pod" data-id="${c.pod}">← ${p.name} / case selection</button><header class="case-heading"><div><p class="eyebrow" style="color:${p.color}">${c.level} · ${p.type} · ${r.mode==='coached'?'COACHED SHIFT':'INDEPENDENT SHIFT'}</p><h1>${c.title}</h1><div class="patient">${c.patient}<br>${c.device}</div></div><div class="case-controls"><span class="clock">${time(r)}<small>SIMULATED / ACTION-BASED TIME</small></span><button class="secondary" data-do="tab" data-id="notes">SBAR + note</button></div></header><div class="care-meter"><span><b>${m.done}/${m.total}</b> care tasks</span><div class="progress-track" role="progressbar" aria-valuenow="${m.done}" aria-valuemin="0" aria-valuemax="${m.total}" aria-label="Care task progress"><i style="width:${100*m.done/m.total}%"></i></div><span class="save-status">Progress saved in this browser</span><button class="quiet" data-do="timeline">Timeline ↗</button></div><div class="case-layout"><aside class="task-panel"><h2>YOUR BEDSIDE PLAN</h2><ul class="tasks">${c.goals.map(g=>`<li><button class="task ${r.flags[g.id]?'done':next?.id===g.id?'next':''}" data-do="task" data-id="${g.id}"><span class="square">${r.flags[g.id]?'✓':''}</span>${g.label}</button></li>`).join('')}</ul><p class="helper">This list tracks completion, not a mandatory sequence. Respond to instability immediately; urgent assessment and escalation can run in parallel.</p></aside><section class="case-content"><div class="vitals">${Object.entries(r.vitals).map(([k,v])=>`<div class="vital ${k==='MAP'&&v<65?'alert':''}"><span>${k==='MAP'?'SYSTEMIC MAP':k==='UO'?'URINE / LAST HOUR':k}</span><b>${v}<small>${k==='MAP'?'mmHg':k==='UO'?'mL in previous hour':k==='HR'?'beats/min':'%'}</small></b></div>`).join('')}</div><div class="alarm ${c.monitor&&['deep','shallow'].includes(r.monitor.pattern)?'position':''}">! ${esc(r.alarm)} <button style="float:right;font-size:10px;text-decoration:underline;color:inherit" data-do="tab" data-id="actions">Respond →</button></div>${nextFocus(next)}<nav class="tabs" aria-label="Case workspace">${[['brief','Report'],['bedside','Bedside'],...(c.monitor?[['device','Device']]:[]),['orders','Orders + labs'],['actions','Act'],['notes','Document']].map(([id,label])=>`<button data-do="tab" data-id="${id}" class="${tab===id?'active':''}" aria-current="${tab===id?'page':'false'}">${label}</button>`).join('')}</nav><div class="content-panel" id="casePanel">${caseResponse(r)}${caseContent(c,r)}</div></section></div>`;
}
function caseContent(c,r){
 if(tab==='brief')return `<div class="card"><div class="bedside-header">${portrait}<div><p class="eyebrow">INCOMING NURSE</p><h2 style="font-size:23px;margin-bottom:0">Here’s where we are.</h2></div></div><p class="muted" style="margin-top:18px;font-size:14px">${c.intro}</p>${r.flags.report?`<ul class="handoff-lines">${c.handoff.map(x=>`<li>${x}</li>`).join('')}</ul><span class="badge">✓ BASELINE RECEIVED</span>`:`<button class="primary" data-do="observe" data-id="report">Receive report →</button>`}</div><div class="callout gold"><strong>At the bedside:</strong> ${c.targets} You can open <strong>Act</strong> now; do not finish a routine checklist before responding to an unstable patient.</div><div class="buttons"><button class="secondary" data-do="tab" data-id="bedside">Assess patient →</button><button class="secondary" data-do="tab" data-id="actions">Urgent actions →</button></div>`;
 if(tab==='bedside')return `<p class="helper">Tap an assessment to obtain the finding. In coached mode, you also get the reason it matters.</p><div class="assess-grid">${c.assessments.map(o=>`<article class="assess-card" id="obs-${o.id}"><h3>${r.flags[o.id]?'✓ ':''}${o.title}</h3>${r.flags[o.id]?`<span class="finding-label">INITIAL CASE FINDING</span><p>${o.result}</p>${r.mode==='coached'?`<div class="rationale">${o.why}</div>`:''}`:`<p>Obtain the finding before choosing a cause-specific action.</p><button class="secondary" data-do="observe" data-id="${o.id}">Assess →</button>`}</article>`).join('')}</div><div class="buttons" style="margin-top:18px"><button class="secondary" data-do="tab" data-id="actions">Open actions →</button></div>`;
 if(tab==='device')return controller(c,r)+`<div class="callout"><strong>Patient first.</strong> These placement signals may become misleading with malposition. Compare with a reliable systemic arterial pressure, the patient, the external mark and imaging.</div><div class="buttons"><button class="secondary" data-do="observe" data-id="waves">${r.flags.waves?'Review interpretation':'Compare the three signals'} →</button>${c.lecturePhoto===false?'':'<button class="quiet" data-do="photo">Lecture photo ↗</button>'}</div>${r.flags.waves?`<div class="card" style="margin-top:16px"><h3>Recorded findings at alarm onset</h3><p class="muted" style="font-size:14px">${c.assessments.find(o=>o.id==='waves').result}</p></div>`:''}`;
 if(tab==='orders')return `<div class="callout"><strong>Verify, don’t assume.</strong> These orders belong to this fictional case. Actual drug rates, targets, laboratory intervals and nursing authority come from the active patient orders and local policy.</div><section class="card"><h3>Orders and medications</h3>${c.orders.map(([name,status,detail])=>`<div class="order"><div><h3>${name}</h3><p>${detail}</p></div><span class="badge status-${status.toLowerCase()}">${status.toUpperCase()}</span></div>`).join('')}</section><section class="card"><h3>Labs I connect to the bedside</h3><div class="table-wrap"><table><thead><tr><th>LAB / RESULT</th><th>CASE SCHEDULE</th><th>WHY I CARE</th></tr></thead><tbody>${c.labs.map(([name,value,unit,normal,when,why])=>`<tr><td>${name}<br><strong>${r.labUpdates[name]||value}</strong> ${unit}<small>Reference: ${normal}</small></td><td>${when}</td><td>${why}</td></tr>`).join('')}</tbody></table></div></section><button class="primary" data-do="observe" data-id="orders">${r.flags.orders?'✓ Orders reviewed':'Reconcile orders and due labs'} →</button>`;
 if(tab==='actions')return `<p class="helper">Assessment, notification and urgent treatment can happen in parallel. A cause-specific treatment still needs the relevant findings and authorization.</p><div class="action-list">${c.actions.filter(a=>!a.unsafe).map(a=>actionCard(a,r)).join('')}</div><details class="safety-options"><summary>Consider other choices / test a shortcut</summary><div class="action-list">${c.actions.filter(a=>a.unsafe).map(a=>actionCard(a,r)).join('')}</div></details><div class="buttons" style="margin-top:20px"><button class="secondary" data-do="tab" data-id="notes">Document what happened →</button></div>`;
 if(tab==='notes')return notes(c,r);
 return '';
}
function actionCard(a,r){const done=r.flags[a.id];return `<article class="action-card ${done?'done':''}"><div class="action-card-head"><div><button data-do="action" data-id="${a.id}" ${done?'disabled':''}>${done?'✓ ':''}${a.label}</button><div class="role">${a.role}</div></div><button class="action-go" data-do="action" data-id="${a.id}" aria-label="${esc(a.label)}" ${done?'disabled':''}>${done?'DONE':'DO →'}</button></div>${a.reasoning&&!done?reasoningChoices(a):''}${a.calculation&&!done?`<div class="calculation"><label for="calc-${a.id}">${a.calculation.prompt}</label><input id="calc-${a.id}" type="number" inputmode="decimal" step="any" aria-label="Calculated answer">${a.calculation.units}${r.mode==='coached'?`<p class="helper" style="margin:10px 0 0">${a.calculation.formula}</p>`:''}</div>`:''}${done&&r.mode==='coached'?`<p class="action-feedback">${a.feedback}</p>`:''}</article>`;}
function wavePath(type,width=720,height=112){const pts=[];for(let x=0;x<=width;x+=2){const t=(x%120)/120;let v;if(type==='ao')v=t<.15?.6-t*2.8:t<.3?.18+(t-.15)*.9:t<.42?.32+(t-.3)*1.2:t<.47?.46-(t-.42)*1.2:.4+(t-.47)*.38;else if(type==='lv'||type==='suction')v=t<.12?.82-t*5.2:t<.34?.2+Math.sin((t-.12)*9)*.025:t<.48?.2+(t-.34)*4.5:.82;if(type==='suction'&&t>.48&&t<.82)v=1.02-(t-.48)*.55;if(type==='motor')v=.53+Math.sin(t*Math.PI*2)*.11+Math.sin(t*Math.PI*4)*.03;if(type==='flat')v=.55+Math.sin(t*6.28)*.008;pts.push(`${x},${Math.round(9+v*(height-18))}`);}return 'M'+pts.join(' L');}
function grid(){let s='';for(let x=0;x<720;x+=30)s+=`<path d="M${x} 0V112"/>`;for(let y=14;y<112;y+=24)s+=`<path d="M0 ${y}H720"/>`;return `<g stroke="#24404b" stroke-width=".6" opacity=".55">${s}</g>`;}
function controller(c,r){const m=r.monitor,display=deviceDisplay(m),ao=display.aoShape,lv=display.lvShape,motor=display.motorShape;return `<section class="controller" aria-label="Illustrative Impella placement display"><div class="controller-heading"><span>LEFT-SIDED SUPPORT / PLACEMENT</span><span>${c.device.includes('5.5')?'5.5':'CP'} · TEACHING DISPLAY</span></div><div class="wave-row"><svg viewBox="0 0 480 112" preserveAspectRatio="none" role="img" aria-label="${display.lvAvailable?'Sensed Ao pressure and calculated LV estimate':'Sensed Ao pressure; LV estimate unavailable at this support level'}">${grid()}<path d="${wavePath(ao)}" fill="none" stroke="#ed9f86" stroke-width="2.6"/><path d="${display.lvAvailable?wavePath(lv):''}" fill="none" stroke="#eff3eb" stroke-width="1.7" ${m.pattern==='deep'?'stroke-dasharray="4 3"':''}/></svg><div class="wave-values"><small>Ao / mmHg</small>${m.ao}<span class="white"><small>Estimated LV</small>${display.lvText}</span></div></div><div class="wave-row"><svg viewBox="0 0 480 112" preserveAspectRatio="none" role="img" aria-label="${motor==='flat'?'Nearly flat':'Pulsatile'} green motor current">${grid()}<path d="${wavePath(motor)}" fill="none" stroke="#76d5ba" stroke-width="2.6"/></svg><div class="wave-values motor"><small>MOTOR CURRENT</small>${motor==='flat'?'LOW':'PULSATILE'}<small>pulsatility</small></div></div><div class="controller-metrics"><div>SUPPORT<b>P${m.p}</b></div><div>PUMP FLOW<b>${Number(m.flow).toFixed(1)} <small>L/min</small></b></div><div>PURGE PRESSURE<b>${m.purgePressure} <small>mmHg</small></b></div><div>PURGE FLOW<b>${m.purgeFlow} <small>mL/h</small></b></div></div><p class="controller-caption">Illustrative waveforms, not calibrated device signals. White LV pressure is calculated. Green is motor current. Pump flow is not total cardiac output. Systemic MAP is shown separately above.</p><p class="controller-caption">${esc(display.lvMessage)}</p>${m.purgeStatus?`<p class="purge-status">${esc(m.purgeStatus)}</p>`:''}<details class="signal-guide"><summary>How the three signals relate</summary><dl><dt>Ao: a sensed placement pressure</dt><dd>The optical sensor normally sits in the aorta. If it moves across the valve, the red waveform may no longer represent systemic arterial pressure.</dd><dt>LV: a calculated estimate</dt><dd>The controller combines placement and pump information to estimate LV pressure. It is not a second pressure catheter, and it is unavailable at P3 and below.</dd><dt>Motor current: electrical load</dt><dd>The load changes with pump speed and the inlet-to-outlet pressure difference. A changing pressure difference during the cardiac cycle creates pulsatility. A flat trace also needs interpretation alongside native cardiac activity, position and the patient.</dd></dl><p>These drawings are illustrative. Use the patient, reliable systemic arterial pressure and the trained team's position assessment together.</p></details></section>`;}

function nextFocus(next){return next?`<div class="next-task"><span><small>STILL TO CHECK</small><strong>${esc(next.label)}</strong></span><button class="secondary" data-do="task" data-id="${esc(next.id)}">Open task →</button></div>`:'';}
function caseResponse(r){return r.latestResponse?`<section class="case-response" aria-label="Latest case response"><h3>Latest response · ${esc(r.latestResponse.time)}</h3><p>${esc(r.latestResponse.text)}</p><small>Scripted case event. Initial assessment cards retain the starting findings.</small></section>`:'';}
function reasoningChoices(a){return `<fieldset class="reasoning-choice" id="choice-${a.id}"><legend>${esc(a.reasoning.prompt)}</legend>${a.reasoning.options.map(o=>`<label class="choice-option"><input type="radio" name="choice-${a.id}" value="${esc(o.id)}"><span>${esc(o.label)}</span></label>`).join('')}</fieldset>`;}
function stopSpeech(){if(activeSpeech){const previous=activeSpeech;activeSpeech=null;try{previous.abort();}catch{}}}
function showSources(){
 const c=CASE_BY_ID[caseId],ids=c?.sourceIds||(c?.pod==='delta'?[c.device.includes('5.5')?'impella-55':'impella-cp']:[]);
 const sources=c?CLINICAL_SOURCES.filter(s=>ids.includes(s.id)):CLINICAL_SOURCES;
 showModal(`<p class="eyebrow">CLINICAL BASIS / OCTOBER 20, 2026</p><h2>Sources checked. Clinical review still pending.</h2><p>These source checks cover the Delta display rules and the cited floor-workflow principles. Each source entry states its scope. Patient details, orders, targets, nursing permissions, lab timing and responses are fictional case instructions. They do not establish a hospital protocol.</p>${sources.length?sources.map(s=>`<article class="source-entry"><h3><a href="${s.url}" target="_blank" rel="noopener noreferrer">${esc(s.title)} ↗</a></h3><p>${esc(s.detail)}</p></article>`).join(''):'<p>This Delta review pass does not establish a completed review of the Bravo cases.</p>'}<p>The study guide was sent for nurse-manager recommendations. Approval has not been established. The game remains an unvalidated educational prototype; note checking measures completeness only.</p>`);
}

const fields=[['s','S · What changed?','State the immediate problem and when it began.'],['b','B · What is the context?','Device, diagnosis, baseline support and relevant prior treatment.'],['a','A · What did you assess?','Actual perfusion, pressures, access and lab findings.'],['r','R · What did you request / do?','Who was notified, what was requested, and actions under orders.'],['response','Response · What happened next?','Response to treatment, ongoing concern and next reassessment.']];
function notes(c,r){return `<div class="callout"><strong>Make the next nurse’s job easier.</strong> Include the change, objective findings, actions, notification, response and follow-up. Type or use the mic if supported; phone keyboard dictation also works. Use fictional case details only.</div><div class="note-grid">${fields.map(([k,label,placeholder])=>`<label class="note-field ${k==='response'?'wide':''}"><span class="field-top">${label}<button class="dictate" type="button" data-do="dictate" data-id="${k}">Mic</button></span><textarea id="note-${k}" data-note="${k}" placeholder="${placeholder}">${esc(r.note[k])}</textarea></label>`).join('')}</div><p class="helper" style="margin:14px 0">The prototype checks whether each section has content. It does <strong>not</strong> validate clinical accuracy, invent findings, or issue a competency certification.</p><div class="buttons"><button class="primary" data-do="finish">Complete handoff →</button><button class="secondary" data-do="export">Export my note</button><button class="quiet" data-do="timeline">Review timeline ↗</button>${r.mode==='coached'?'<button class="quiet" data-do="example">Example note ↗</button>':''}</div>`;}
function renderDebrief(){const r=run(),c=CASE_BY_ID[caseId],m=metrics(r);app.innerHTML=`<button class="back" data-do="pod" data-id="${c.pod}">← Back to pod</button><section class="debrief-hero"><p class="eyebrow">${c.level} / SHIFT DEBRIEF</p><h1>The handoff is part<br>of the care.</h1><p class="muted">${c.title} · ${time(r)} simulated time</p><div class="debrief-metrics"><div><strong>${m.done}/${m.total}</strong><span>care tasks completed</span></div><div><strong>${m.safetyStops}</strong><span>choices stopped for safety</span></div><div><strong>5/5</strong><span>handoff fields completed</span></div></div><div class="buttons"><button class="primary" data-do="pod" data-id="${c.pod}">Choose another patient →</button><button class="secondary" data-do="replay" data-id="${c.id}">Replay this shift</button></div></section><div class="case-grid"><section class="card"><h2>What this case was teaching</h2><ul class="debrief-list">${c.debrief.map(t=>`<li>${t}</li>`).join('')}</ul>${r.issues.length?`<h3>Decisions to revisit</h3><ul class="debrief-list">${r.issues.map(i=>`<li>${esc(i.text)}</li>`).join('')}</ul>`:'<p class="helper">No unsafe shortcut was selected. That reflects these scripted tasks, not a certification of bedside competence.</p>'}</section><section class="card"><h2>Your handoff</h2><div class="note-example">${fields.map(([k,label])=>`<strong>${label}</strong>\n${esc(r.note[k])}`).join('\n\n')}</div><div class="buttons" style="margin-top:20px"><button class="secondary" data-do="export">Export my note</button><button class="quiet" data-do="example">Compare with example ↗</button></div></section></div><section class="card"><h2>Action timeline</h2>${timelineHTML(r)}</section><div class="callout"><strong>Help shape the next version.</strong> A useful review catches ambiguous choices, missing assessment options and local-policy differences. <button class="quiet" data-do="review" style="color:var(--mint);text-decoration:underline">Leave a review note ↗</button></div>`;}
function timelineHTML(r){return `<ol class="timeline">${r.history.length?r.history.map(e=>`<li class="${e.kind==='unsafe'?'unsafe':''}"><time>${esc(e.time)}</time><span>${esc(e.text)}${e.detail?`<small class="event-detail">${esc(e.detail)}</small>`:''}</span></li>`).join(''):'<li>No actions recorded yet.</li>'}</ol>`;}
function showModal(html){pressed.clear();stopSpeech();$('#modalBody').innerHTML=html;const d=$('#modal');if(!d.open)d.showModal();}
function showGuide(){showModal(`<p class="eyebrow">POCKET GUIDE / REASON BEFORE YOU REACT</p><h2>Connect the number to the patient.</h2><div class="formula-grid"><div class="formula"><b>PAPi = (PAs − PAd) ÷ mean RA</b>RA is often represented by CVP. A low or falling result can support concern for RV dysfunction in context. Echo, loading conditions and the clinical picture still matter.</div><div class="formula"><b>CPO = MAP × CO ÷ 451</b>MAP in mmHg; total CO in L/min; output in watts. Use a trustworthy systemic pressure and total CO, not pump flow alone.</div><div class="formula"><b>CPP = MAP − ICP</b>Both pressures in mmHg. ICP problems and systemic hypotension can both threaten cerebral perfusion. Follow the patient’s prescribed targets.</div><div class="formula"><b>Fluid target = kg × ordered mL/kg</b>Subtract verified prior resuscitation where the order calls for it. An arithmetic target does not remove the need to reassess response and congestion.</div></div><h3 style="margin-top:25px">Albumin: concentration is not the dose.</h3><p><strong>5%</strong> contains 5 g per 100 mL. <strong>25%</strong> contains 25 g per 100 mL and delivers the same grams in a smaller volume. Concentrated albumin can expand circulating volume by recruiting fluid; it can still cause cardiovascular overload. The indication and patient’s volume status decide the plan.</p><div class="guide-fields"><label>Ordered grams<input id="albuminGrams" type="number" min="0.1" step="any" value="25" inputmode="decimal"></label><label>Concentration<select id="albuminPercent"><option value="5">5%</option><option value="25">25%</option></select></label><button class="secondary" data-do="albumin">Calculate volume</button></div><div id="albuminResult" class="guide-result" aria-live="polite">25 g of 5% = 500 mL</div><p class="helper">25 g of 25% = 100 mL. A 50 mL bottle of 25% contains 12.5 g. “25% versus 50 mL” compares concentration with bottle volume. This calculator checks arithmetic, not the appropriateness of an order.</p><div class="callout gold"><strong>Two easy traps:</strong> high CVP does not prove the patient needs fluid; heart failure does not automatically prohibit every fluid challenge. Assess perfusion, congestion, response and the active plan.</div>`);}
function exportNote(){const r=run(),c=CASE_BY_ID[caseId];const text=`SHIFT: ICU | FICTIONAL TRAINING CASE\n${c.title}\n${c.patient}\nCompleted: ${r.finished?'yes':'no'} | Simulated time ${time(r)}\n\n${fields.map(([k,label])=>label+'\n'+r.note[k]).join('\n\n')}\n\nACTION TIMELINE\n${r.history.map(e=>e.time+' '+e.text+(e.detail?'\n'+e.detail:'')).join('\n')}\n\nCompleteness checklist only; no clinical accuracy or competency certification.\nCreated by Rafael Gallardo, RN.`;download('SHIFT_ICU_'+c.id+'_practice_note.txt',text,'text/plain');}
function download(name,text,type){const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function speak(field){const Recognition=window.SpeechRecognition||window.webkitSpeechRecognition;if(!Recognition){toast('This browser does not expose speech recognition. Tap the note field and use the microphone on your phone keyboard, or type.');$('#note-'+field)?.focus();return;}if(activeSpeech){activeSpeech.abort();activeSpeech=null;return;}const recognition=new Recognition();recognition.lang='en-US';recognition.interimResults=false;recognition.continuous=false;const target=$('#note-'+field),owner=run(),ownerCase=caseId;recognition.onresult=e=>{const text=Array.from(e.results).map(x=>x[0].transcript).join(' ');if(ownerCase!==caseId||screen!=='case'||!target?.isConnected)return;if(owner&&target){owner.note[field]=[target.value,text].filter(Boolean).join(' ');target.value=owner.note[field];save();}toast('Dictation added. Check the transcription before handing off.');};recognition.onerror=()=>{toast('Dictation could not start. Use your phone keyboard’s microphone or type instead.');activeSpeech=null;};recognition.onend=()=>{activeSpeech=null;};try{recognition.start();activeSpeech=recognition;toast('Listening for this note field. Use fictional details only.');}catch{toast('Mic unavailable. Phone keyboard dictation or typing will still work.');}}
function taskTab(id){if(id==='report')return 'brief';if(id==='document')return 'notes';if(id==='orders')return 'orders';if(CASE_BY_ID[caseId].assessments.some(o=>o.id===id))return id==='waves'?'device':'bedside';return 'actions';}
document.addEventListener('input',e=>{const key=e.target.dataset.note;if(key&&run()){run().note[key]=e.target.value;save();}});
document.addEventListener('change',e=>{if(e.target.id==='mode'){data.mode=e.target.value;save();}});
document.addEventListener('click',e=>{const b=e.target.closest('[data-do]');if(!b)return;const action=b.dataset.do,id=b.dataset.id;
 if(action==='close')return $('#modal').close();
 if(action==='hub'){screen='hub';render(false);return;}
 if(action==='start')return openShift('delta');
 if(action==='shift')return openShift(id||'delta');
 if(action==='pod')return openPod(id);
 if(action==='case')return openCase(id);
 if(action==='replay'){showModal(`<p class="eyebrow">START A FRESH SHIFT</p><h2>Replay this case?</h2><p>The previous practice note and timeline for this case will be replaced. Export your note first if you want to keep it.</p><div class="buttons"><button class="primary" data-do="restartConfirmed" data-id="${id}">Start fresh →</button><button class="secondary" data-do="close">Keep my progress</button></div>`);return;}
 if(action==='restartConfirmed'){$('#modal').close();return openCase(id,true);}
 if(action==='tab'){tab=id;render();return;}
 if(action==='task'){tab=taskTab(id);render();setTimeout(()=>$('#obs-'+id)?.scrollIntoView({block:'center',behavior:'smooth'}),50);return;}
 if(action==='observe'){const c=CASE_BY_ID[caseId];observe(run(),id);save();render();if(id==='waves'&&tab==='device')toast(c.assessments.find(o=>o.id==='waves').result);else playTone(600);return;}
 if(action==='action'){const answer=$('#choice-'+id+' input:checked')?.value??$('#calc-'+id)?.value;const result=act(run(),id,answer);save();render();toast(result.text,!!result.safety);playTone(result.safety?180:660,result.safety?.2:.09);return;}
 if(action==='finish'){const result=finish(run());save();if(!result.ok)return toast(result.text);screen='debrief';render(false);playTone(880,.2);return;}
 if(action==='guide')return showGuide();
 if(action==='sources')return showSources();
 if(action==='albumin'){const g=Number($('#albuminGrams').value),p=Number($('#albuminPercent').value),v=albuminVolume(g,p);$('#albuminResult').textContent=v===null?'Enter a positive dose in grams.':`${g} g of ${p}% = ${Number(v.toFixed(2))} mL`;return;}
 if(action==='timeline')return showModal(`<p class="eyebrow">${esc(CASE_BY_ID[caseId].level)} / YOUR ACTIONS</p><h2>Shift timeline</h2><p>Time advances only with the case’s scripted actions. No real-time clock is running against you.</p>${timelineHTML(run())}`);
 if(action==='export')return exportNote();
 if(action==='dictate')return speak(id);
 if(action==='example')return showModal(`<p class="eyebrow">FICTIONAL EXAMPLE / NOT AN AUTOMATIC NOTE</p><h2>One way to hand this off</h2><p class="note-example">${CASE_BY_ID[caseId].exampleNote}</p><p class="helper">Use only findings actually assessed and actions actually performed. This example describes the intended case path; your own timeline may differ.</p>`);
 if(action==='photo'){const c=CASE_BY_ID[caseId];const src=c.id==='impella-shallow'?'lecture-aorta.jpg':c.id==='impella-deep'?'lecture-ventricle.jpg':'lecture-suction.jpg';return showModal(`<p class="eyebrow">FROM THE LECTURE / COMPARE THE PATTERN</p><h2>${c.id.includes('shallow')?'Position in aorta':c.id.includes('deep')?'Position in ventricle':'Diastolic suction'}</h2><img class="lecture-photo" src="assets/${src}" alt="Lecture slide showing ${esc(c.subtitle)}"><p class="helper">Numbers in this teaching case may differ from the slide. Compare the pattern, the sensed Ao pressure, calculated LV estimate and motor-current pulsatility.</p>`);}
 if(action==='sound')return toggleSound();
 if(action==='interact')return enterNearest();
 if(action==='how')return showModal(`<p class="eyebrow">CLOCK IN / FLOOR SHIFT</p><h2>Work the floor.</h2><ol><li>Choose your pod and receive a new room / patient assignment.</li><li>Walk to charge or the nursing station for report.</li><li>Visit the bedside for assessment and the computer for orders, MAR, worklist, labs and documentation.</li><li>Pack supplies, prepare admissions and respond to patient changes.</li><li>Keep up with repeated care, reassess responses and hand off remaining concerns.</li></ol><p>Use arrows / WASD, the touch pad, or tap-to-walk. Room cards guide you through the doors; E or the large interaction button opens the nearby workspace.</p><p>Coached mode pauses the clock while reading. Independent mode keeps the compressed clock running. Equipment drills have a separate optional timer. You can pause, save and export the shift journal.</p><h3>Focused bedside practice</h3><p>The separate Impella, sepsis and DKA cases remain available from the hospital menu. Their case clock is action-based rather than real-time.</p><p>Patients, orders and outcomes are fictional. This is not a continuous physiology model, a hospital protocol or a validated competency assessment.</p>`);
 if(action==='about')return showModal(`<p class="eyebrow">CREATED BY RAFAEL GALLARDO, RN</p><h2>A small first shift. A bigger hospital.</h2><p>The walkable floor now has generated room assignments, bedside care, room computers, supply preparation, admission readiness and recurring care. Its cardiac, medical, neuro and IMC cases are a first shift framework; they are not complete specialty curricula. Eight focused bedside cases remain available.</p><p>Original retro map and teaching controller. Device signals are schematic, and outcomes are scripted. This is not an official hospital or manufacturer product and has not been validated for clinical training or bedside decisions.</p><h3>What comes next</h3><ul><li>Clinical review of every decision, order set and debrief.</li><li>More varied shifts, equipment interactions and reviewed clinical pathways.</li><li>ECMO and deeper CABG, EVD, renal and ventilator pathways.</li><li>More detailed medication tasks and local-protocol versions.</li><li>Richer documentation review, with transparent limits.</li></ul><p>Browser speech input is optional and browser-dependent. No AI note-grading service is connected. Progress and typed practice notes are saved in this browser.</p><button class="secondary" data-do="review">Open review worksheet →</button>`);
 if(action==='review'){const c=CASE_BY_ID[caseId];showModal(`<p class="eyebrow">CLINICAL / GAMEPLAY REVIEW</p><h2>What should we change?</h2><p>Review notes stay in this browser until you export them. Nothing is sent to a manager automatically.</p><div class="review-grid"><label>Case / pod<input id="reviewCase" value="${esc(c?.title||'Overall game')}"></label><label>Issue type<select id="reviewType"><option>Clinical accuracy</option><option>Local policy difference</option><option>Missing assessment or action</option><option>Gameplay / usability</option></select></label><label class="wide">Finding<textarea id="reviewFinding" placeholder="What is unclear, incorrect, or missing?"></textarea></label><label class="wide">Suggested correction and basis<textarea id="reviewFix" placeholder="What would improve this? Include the applicable policy or source when relevant."></textarea></label></div><div class="buttons" style="margin-top:18px"><button class="primary" data-do="exportReview">Export review note</button></div>`);return;}
 if(action==='exportReview'){const note={build:'SHIFT ICU v0.3',case:$('#reviewCase').value,type:$('#reviewType').value,finding:$('#reviewFinding').value,correction:$('#reviewFix').value};if(!note.finding.trim())return toast('Add the finding you want reviewed first.');data.review=note;save();download('SHIFT_ICU_review.txt',Object.entries(note).map(([k,v])=>k.toUpperCase()+': '+v).join('\n\n'),'text/plain');return;}
});
document.querySelector('.brand').addEventListener('click',e=>{e.preventDefault();screen='hub';render(false);});
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal'))$('#modal').close();});
document.addEventListener('visibilitychange',()=>{pressed.clear();if(document.hidden&&activeSpeech){activeSpeech.abort();activeSpeech=null;}});
window.addEventListener('blur',()=>pressed.clear());
const doors=[{id:'alpha',x:240,y:219},{id:'bravo',x:720,y:219},{id:'charlie',x:240,y:301},{id:'delta',x:720,y:301}];
function enterNearest(){if(screen!=='hub')return;const closest=doors.toSorted((a,b)=>Math.hypot(a.x-mapPlayer.x,a.y-mapPlayer.y)-Math.hypot(b.x-mapPlayer.x,b.y-mapPlayer.y))[0];if(Math.hypot(closest.x-mapPlayer.x,closest.y-mapPlayer.y)<135)openShift(closest.id);else toast('Walk toward a pod door, tap a room, or use its card below.');}
document.addEventListener('keydown',e=>{if(screen!=='hub'||$('#modal').open||/INPUT|TEXTAREA|SELECT/.test(e.target.tagName))return;if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();pressed.add(e.key.replace('Arrow','').toLowerCase());}if(e.key==='Enter'||e.key===' ') {e.preventDefault();enterNearest();}});
document.addEventListener('keyup',e=>pressed.delete(e.key.replace('Arrow','').toLowerCase()));
document.addEventListener('pointerdown',e=>{const b=e.target.closest('[data-move]');if(b){e.preventDefault();pressed.add(b.dataset.move);b.setPointerCapture?.(e.pointerId);}});
document.addEventListener('lostpointercapture',()=>pressed.clear());window.addEventListener('pagehide',()=>{pressed.clear();stopSpeech();});
document.addEventListener('pointerup',()=>pressed.clear());document.addEventListener('pointercancel',()=>pressed.clear());
function initMap(){const canvas=$('#hospitalMap'),ctx=canvas.getContext('2d');if(!ctx)return;ctx.imageSmoothingEnabled=false;canvas.addEventListener('click',e=>{const b=canvas.getBoundingClientRect(),x=(e.clientX-b.left)*960/b.width,y=(e.clientY-b.top)*520/b.height;const p=x<480?(y<260?'alpha':'charlie'):(y<260?'bravo':'delta');openShift(p);});let prev=0;const reduced=window.matchMedia?.('(prefers-reduced-motion: reduce)').matches;
 const rect=(x,y,w,h,color)=>{ctx.fillStyle=color;ctx.fillRect(Math.round(x),Math.round(y),w,h);};
 const bed=(x,y,accent)=>{rect(x+4,y+7,90,46,'#0c1925');rect(x,y,86,40,'#a2b3ad');rect(x+5,y+5,75,30,'#e0e5d7');rect(x+9,y+7,17,25,'#f5f2df');rect(x+31,y+5,48,30,accent);rect(x+9,y-4,15,15,'#c4926e');rect(x+8,y-5,16,5,'#3e3633');rect(x+5,y+40,8,8,'#6f8585');rect(x+73,y+40,8,8,'#6f8585');};
 const monitor=(x,y,accent,t)=>{rect(x,y,45,32,'#687d82');rect(x+4,y+4,37,23,'#08191e');ctx.strokeStyle=accent;ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(x+7,y+17);ctx.lineTo(x+14,y+17);ctx.lineTo(x+18,y+10);ctx.lineTo(x+22,y+24);ctx.lineTo(x+27,y+15);ctx.lineTo(x+37,y+15);ctx.stroke();rect(x+19,y+32,7,13,'#687d82');rect(x+11,y+43,25,4,'#687d82');};
 function room(x,y,p,t){const w=412,h=182;rect(x,y,w,h,'#162d39');rect(x+6,y+6,w-12,h-12,'#223c48');for(let tx=x+10;tx<x+w-10;tx+=32)for(let ty=y+10;ty<y+h-10;ty+=32)rect(tx,ty,30,30,((tx+ty)%3)?'#233d48':'#253f4a');rect(x,y,w,6,p.color);rect(x,y,6,h,'#3b5362');rect(x+w-6,y,6,h,'#3b5362');rect(x,y+h-6,w,6,'#3b5362');const doorY=y<100?y+h-6:y;rect(x+w/2-26,doorY,52,6,p.color);rect(x+16,y+14,140,25,'#13232f');ctx.fillStyle=p.color;ctx.font='bold 14px monospace';ctx.fillText(p.name+' / '+p.type.split(' ')[0].toUpperCase(),x+23,y+31);bed(x+56,y+77,p.color);bed(x+244,y+77,p.color);monitor(x+153,y+72,p.color,t);monitor(x+344,y+72,p.color,t);rect(x+w-42,y+20,22,25,'#547568');rect(x+w-47,y+12,30,18,'#6c9a77');rect(x+24,y+139,47,17,'#758f93');rect(x+28,y+137,40,3,'#bed3cb');}
 function draw(ts){const dt=Math.min((ts-prev)/1000||0,.04);prev=ts;const speed=180*dt;let dx=(pressed.has('right')?1:0)-(pressed.has('left')?1:0),dy=(pressed.has('down')?1:0)-(pressed.has('up')?1:0);if(dx&&dy){dx*=.707;dy*=.707;}mapPlayer.x=Math.max(22,Math.min(938,mapPlayer.x+dx*speed));mapPlayer.y=Math.max(220,Math.min(298,mapPlayer.y+dy*speed));rect(0,0,960,520,'#101f2a');rect(0,219,960,83,'#344752');for(let x=0;x<960;x+=32)for(let y=221;y<300;y+=26)rect(x+1,y+1,30,24,'#3a4e58');rect(474,20,12,480,'#334957');room(34,31,PODS[0],ts);room(514,31,PODS[1],ts);room(34,307,PODS[2],ts);room(514,307,PODS[3],ts);rect(426,237,108,40,'#1b303d');rect(430,241,100,32,'#5a7f7e');ctx.fillStyle='#c0d7cf';ctx.font='bold 10px monospace';ctx.fillText('NURSES’',454,252);ctx.fillText('STATION',454,266);const px=Math.round(mapPlayer.x),py=Math.round(mapPlayer.y)+(reduced?0:Math.sin(ts/200)*1.2);ctx.fillStyle='#07131a66';ctx.fillRect(px-11,py+13,26,5);rect(px-6,py-21,16,6,'#403536');rect(px-7,py-15,18,14,'#d5a27c');rect(px-10,py-2,24,17,'#aaa4ee');rect(px-3,py-2,10,5,'#68689a');rect(px-13,py+2,4,12,'#d5a27c');rect(px+14,py+2,4,12,'#d5a27c');rect(px-7,py+15,7,8,'#091725');rect(px+5,py+15,7,8,'#091725');rect(px+8,py+3,4,6,'#f3f0df');if(!reduced){const pulse=.5+.5*Math.sin(ts/500);ctx.fillStyle=`rgba(118,213,186,${.15+pulse*.2})`;ctx.fillRect(px-8,py-33,19,3);}frame=requestAnimationFrame(draw);}
 frame=requestAnimationFrame(draw);
}
render(false);
